class ApiError extends Error { status: number; constructor(message: string, status: number) { super(message); this.status = status } }

async function request<T>(path: string, token?: string, init: RequestInit = {}): Promise<T> {
  const activeToken = localStorage.getItem('scmsToken') || token
  const response = await fetch(`${API}${path}`, { ...init, headers: { 'Content-Type': 'application/json', ...(activeToken ? { Authorization: `Bearer ${activeToken}` } : {}), ...init.headers } })
  const body = await response.json().catch(() => ({}))
  if (response.status === 401 && activeToken && path !== '/auth/refresh') {
    const refreshToken = localStorage.getItem('scmsRefreshToken')
    if (refreshToken) {
      const refreshed = await refreshAccessToken(refreshToken)
      if (refreshed) return request<T>(path, refreshed, init)
    }
  }
  if (!response.ok || body.success === false) {
    const validationDetails = Array.isArray(body.errors)
      ? body.errors.map((entry: { field?: string; message?: string }) => [entry.field, entry.message].filter(Boolean).join(': ')).filter(Boolean).join('; ')
      : ''
    throw new ApiError(`${body.message || `Request failed (${response.status})`}${validationDetails ? `: ${validationDetails}` : ''}`, response.status)
  }
  return body.data as T
}
type PageInfo = { total: number; page: number; limit: number; pages: number }
async function requestPage<T>(path: string, token?: string): Promise<{ data: T; pagination: PageInfo }> {
  const activeToken = localStorage.getItem('scmsToken') || token
  const response = await fetch(`${API}${path}`, { headers: { 'Content-Type': 'application/json', ...(activeToken ? { Authorization: `Bearer ${activeToken}` } : {}) } })
  const body = await response.json().catch(() => ({}))
  if (response.status === 401 && activeToken) {
    const refreshToken = localStorage.getItem('scmsRefreshToken')
    if (refreshToken) { const refreshed = await refreshAccessToken(refreshToken); if (refreshed) return requestPage<T>(path, refreshed) }
  }
  if (!response.ok || body.success === false) throw new ApiError(body.message || `Request failed (${response.status})`, response.status)
  return { data: body.data as T, pagination: body.pagination as PageInfo }
}
let refreshRequest: Promise<string | null> | null = null
async function refreshAccessToken(refreshToken: string): Promise<string | null> {
  if (!refreshRequest) {
    refreshRequest = (async () => {
      try {
        const response = await fetch(`${API}/auth/refresh`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refreshToken }) })
        const body = await response.json().catch(() => ({}))
        if (!response.ok || body.success === false || !body.data?.accessToken) return null
        localStorage.setItem('scmsToken', body.data.accessToken)
        if (body.data.refreshToken) localStorage.setItem('scmsRefreshToken', body.data.refreshToken)
        return body.data.accessToken as string
      } catch { return null }
      finally { refreshRequest = null }
    })()
  }
  return refreshRequest
}
function savedUser(): User | null { try { return JSON.parse(localStorage.getItem('scmsUser') || 'null') as User | null } catch { return null } }
const money = (n: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(n || 0)
function completeMonthlySeries(rows: Revenue['revenueByMonth'], count: number): Revenue['revenueByMonth'] {
  const now = new Date(); const values = new Map(rows.map(row => [row.month, row]))
  return Array.from({ length: count }, (_, index) => {
    const monthDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - count + index + 1, 1))
    const month = `${monthDate.getUTCFullYear()}-${String(monthDate.getUTCMonth() + 1).padStart(2, '0')}`
    return values.get(month) || { month, revenue: 0, orders: 0 }
  })
}
function periodChange(current: number, previous: number): { label: string; value?: number; direction: 'up' | 'down' | 'flat' } {
  if (previous === 0) return current > 0 ? { label: 'New', direction: 'up' } : { label: '0%', value: 0, direction: 'flat' }
  const value = Math.round(((current - previous) / previous) * 100)
  return { label: `${value > 0 ? '+' : ''}${value}%`, value, direction: value > 0 ? 'up' : value < 0 ? 'down' : 'flat' }
}

